#!/usr/bin/env bash\nset -e\n\n# Build the Docker image (quiet output)\ndocker build -t nightly-quote-server-test . > /dev/null\n\n# Run container in background, mapping host port 5001 -> container port 5000\ncontainer_id=$(docker run -d -p 5001:5000 nightly-quote-server-test)\n\n# Give the server a moment to start\nsleep 2\n\n# Query the second quote (i=1)\nresponse=$(curl -s http://localhost:5001/quote?i=1)\n\n# Expected JSON response\nexpected='{'\"quote\":\"Even in the wasteland, hope sprouts.\"'}'\n\nif [ "$response" = "$expected" ]; then\n  echo "Test passed"\nelse\n  echo "Test failed: got $response"\n  docker rm -f $container_id > /dev/null\n  exit 1\nfi\n\n# Clean up the container\ndocker rm -f $container_id > /dev/null\n\n# End of test\n
